 eye:'M2 12c6-10 14-10 20 0-6 10-14 10-20 0Zm7 0a3 3 0 1 0 6 0 3 3 0 1 0-6 0',
 settings:'M4 7h16M4 17h16M9 4v6M15 14v6',bell:'M5 17h14l-2-3V8a5 5 0 0 0-10 0v6l-2 3ZM10 21h4',
